from pathlib import Path
from PIL import Image,ImageDraw
import base64,json
p=Path(__file__).parent; board=Image.open(p/'board-review-background.png').convert('RGBA'); imgs={n:Image.open(p/'previews'/f'{n}-36px.png') for n in ['idle','attack','recovery']}; scale=36/681; pivot=(448*scale,704*scale); cx=round((238-58)*320/432);cy=round((374-195)*320/433);pos=(round(cx-pivot[0]),round(cy+18-pivot[1])); frames=[]
for n in ['idle','attack','recovery','idle']:
 c=Image.new('RGB',(620,380),'#09131e');d=ImageDraw.Draw(c);d.text((15,10),'Popo v5 / 36px body / visual clip, not runtime timing',fill='#eeeeee');b=board.copy();b.alpha_composite(imgs[n],pos);c.paste(b.convert('RGB'),(15,45));d.text((360,48),n+' / 4x detail',fill='#eeeeee');detail=Image.new('RGBA',imgs[n].size,'#65717d');detail.alpha_composite(imgs[n]);c.paste(detail.resize((imgs[n].width*4,imgs[n].height*4),Image.Resampling.NEAREST).convert('RGB'),(360,80));frames.append(c)
frames[0].save(p/'playback-36px.gif',save_all=True,append_images=frames[1:],duration=[120,100,140,640],loop=0,disposal=2)
def data(impath):return 'data:image/png;base64,'+base64.b64encode(impath.read_bytes()).decode()
assets={n:data(p/'previews'/f'{n}-36px.png') for n in imgs}; bg=data(p/'board-review-background.png')
html='''<!doctype html><meta charset="utf-8"><title>Popo v5 36px review</title><style>body{background:#09131e;color:#eee;font:14px sans-serif;margin:24px}#board{position:relative;width:320px;height:320px;float:left;margin:15px 32px 15px 0;background-image:url(BG)}#sprite{position:absolute;left:POSXpx;top:POSYpx;width:47px;height:41px}#detail{width:188px;height:164px;image-rendering:pixelated;background:#65717d}button{margin:8px}#label{display:inline-block;width:190px}</style><h2>Popo v5: actual 36px body</h2><p>Proposed visual-only clip: idle lead-in 120ms → attack 100ms → recovery 140ms. Idle gap 640ms. First and last states use the same idle image: 760ms idle total; no distinct anticipation pose. No core balance change.</p><button id="toggle">Pause</button><button id="step">Next pose</button><span id="label"></span><div style="clear:both"></div><div id="board"><img id="sprite"></div><p>4× nearest detail</p><img id="detail"><p>Static board image, no gameplay or hit synchronization.</p><script>const assets=ASSETS;const order=['idle','attack','recovery','idle'];const durations=[120,100,140,640];let playing=true,index=0,start=performance.now();window.trace=[];function draw(i){index=i;const pose=order[i];sprite.src=assets[pose];detail.src=assets[pose];label.textContent=['idle lead-in','attack','recovery','idle gap'][i]+' '+durations[i]+'ms';document.body.dataset.pose=pose;document.body.dataset.frame=i;window.trace.push({frame:i,pose,time:performance.now()});}draw(0);function tick(t){if(playing&&t-start>=durations[index]){start+=durations[index];draw((index+1)%4);}requestAnimationFrame(tick);}requestAnimationFrame(tick);toggle.onclick=()=>{playing=!playing;start=performance.now();toggle.textContent=playing?'Pause':'Play';};step.onclick=()=>{playing=false;toggle.textContent='Play';draw((index+1)%4);};window.freeze=(i)=>{playing=false;draw(i);};</script>'''.replace('BG',bg).replace('POSX',str(pos[0])).replace('POSY',str(pos[1])).replace('ASSETS',json.dumps(assets))
(p/'viewer.html').write_text(html); im=Image.open(p/'playback-36px.gif'); print('gif_frames',im.n_frames); print('durations',[((im.seek(i)),im.info['duration'])[1] for i in range(im.n_frames)]);print('position',pos)
